namespace Aspose.Pdf.Text;

/// <summary>
/// Self-contained Shift-JIS (codepage 932 / Adobe-Japan1) two-byte code -> Unicode
/// table, for decoding non-embedded predefined RKSJ CMap text (90ms-RKSJ-H, …)
/// without the System.Text.Encoding.CodePages package. Generated from cp932.
/// </summary>
internal static class SjisTable
{
    private static ushort[]? _table;
    private static ushort[] Table => _table ??= Decode(Data);

    // Lead 0x81-0x9F or 0xE0-0xFC; trail 0x40-0xFC excluding 0x7F.
    private static int Index(int lead, int trail)
    {
        int li = lead <= 0x9F ? lead - 0x81 : (0x9F - 0x81 + 1) + (lead - 0xE0);
        int ti = trail < 0x7F ? trail - 0x40 : trail - 0x41;
        return li * 188 + ti;
    }

    /// <summary>Shift-JIS byte-code -> Unicode codepoint, or null when unmapped.</summary>
    public static int? ToUnicode(int code)
    {
        if (code <= 0x7F) return code;                 // ASCII
        if (code is >= 0xA1 and <= 0xDF) return 0xFF61 + (code - 0xA1); // halfwidth katakana
        int lead = code >> 8, trail = code & 0xFF;
        bool lead2 = lead is (>= 0x81 and <= 0x9F) or (>= 0xE0 and <= 0xFC);
        if (!lead2 || trail < 0x40 || trail > 0xFC || trail == 0x7F) return null;
        var u = Table[Index(lead, trail)];
        return u == 0 ? (int?)null : u;
    }

    private static ushort[] Decode(string b64)
    {
        var raw = System.Convert.FromBase64String(b64);
        var r = new ushort[raw.Length / 2];
        for (int i = 0; i < r.Length; i++)
            r[i] = (ushort)(raw[i * 2] | (raw[i * 2 + 1] << 8));
        return r;
    }

